        ]
      },
      "after": {
        "requirement": "An object-member type mismatch can report the expected and actual types together with the member key.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The object unpacker passes the member key to the type validator, which uses it in the error text. The harness calls json_unpack, whose wrapper passes a null error pointer, and its fixed formats also avoid typed member validation.",
